-- ============================================
-- เตรียมสอบ ก.พ. — Seed Data
-- ข้อมูลเริ่มต้น: 3 หมวดหมู่, 1 ปีตั้งต้น, คำถาม 100 ข้อ, systemConfig เริ่มต้น
--
-- วิธีใช้:
--   - ผ่าน Supabase CLI:  supabase db reset  (รัน migrations + seed อัตโนมัติ)
--   - หรือรันตรงผ่าน Supabase Dashboard → SQL Editor → วางไฟล์นี้ทั้งหมด → Run
--
-- ⚠️ รันครั้งเดียวตอน setup โปรเจกต์ใหม่เท่านั้น รันซ้ำจะสร้างข้อมูลซ้ำ
-- (ไม่มีการเช็ค duplicate เพราะออกแบบมาให้ใช้กับฐานข้อมูลเปล่าเท่านั้น)
-- ============================================

do $$
declare
  v_general_ability_id uuid;
  v_english_id uuid;
  v_civil_service_id uuid;
  v_default_year_id uuid;
begin

  -- ----- หมวดหมู่ -----
  insert into public.categories (name, sort_order) values ('ความสามารถทั่วไป', 0) returning id into v_general_ability_id;
  insert into public.categories (name, sort_order) values ('ภาษาอังกฤษ', 1) returning id into v_english_id;
  insert into public.categories (name, sort_order) values ('การเป็นข้าราชการที่ดี', 2) returning id into v_civil_service_id;

  -- ----- ปีตั้งต้น -----
  insert into public.exam_years (label, year) values ('ทั่วไป (ไม่ระบุปี)', 2568) returning id into v_default_year_id;

  -- ----- คำถามหมวด "ความสามารถทั่วไป" (50 ข้อ) -----
  insert into public.questions (category_id, question_text, options, correct_answer_index, explanation, difficulty, source, created_by)
  select v_general_ability_id, q.question_text, q.options, q.correct_idx,
         '[ยังไม่มีคำอธิบายเฉลย — กรุณาเพิ่มผ่านหน้าจัดการคำถาม]', 'medium', 'manual', null
  from (values
  ('จงหาค่าของ 25×(36÷4)−80+(15×6)', array['185','235','205','215'], 1),
  ('ถ้า 40% ของจำนวนหนึ่งคือ 240 แล้ว 75% ของจำนวนนั้นคือเท่าใด?', array['360','400','450','500'], 2),
  ('อัตราส่วนของครูชายต่อครูหญิงในโรงเรียนแห่งหนึ่งคือ 2:7 ถ้ามีครูชาย 14 คน จะมีครูหญิงกี่คน?', array['35 คน','42 คน','49 คน','56 คน'], 2),
  ('รถไฟขบวนหนึ่งวิ่งด้วยความเร็วเฉลี่ย 120 กิโลเมตรต่อชั่วโมง ใช้เวลา 4 ชั่วโมง 15 นาที ในการเดินทาง รถไฟขบวนนี้เดินทางได้ระยะทางกี่กิโลเมตร?', array['480 กิโลเมตร','500 กิโลเมตร','510 กิโลเมตร','520 กิโลเมตร'], 2),
  ('ถ้า 3y−9=21 แล้วค่าของ y คือเท่าใด?', array['7','8','9','10'], 3),
  ('ร้านค้าซื้อเสื้อมาตัวละ 200 บาท ต้องการขายให้ได้กำไร 30% ร้านค้าจะต้องขายเสื้อตัวละกี่บาท?', array['230 บาท','250 บาท','260 บาท','280 บาท'], 2),
  ('ลำดับตัวเลขต่อไปนี้มีความสัมพันธ์กันอย่างไร? 3, 7, 13, 21, 31, ... จงหาตัวเลขถัดไป', array['41','43','45','47'], 1),
  ('แผนภูมิแท่งแสดงจำนวนนักเรียนที่เข้าร่วมชมรมต่างๆ ดังนี้: ดนตรี 50 คน, กีฬา 60 คน, ศิลปะ 40 คน, วิทยาศาสตร์ 50 คน จงหาว่านักเรียนที่เข้าร่วมชมรมกีฬามีคิดเป็นกี่เปอร์เซ็นต์ของนักเรียนทั้งหมด?', array['25%','30%','35%','40%'], 1),
  ('นาย ข. มีเงิน 10,000 บาท นำไปฝากธนาคารได้ดอกเบี้ย 2.5% ต่อปี เมื่อครบ 1 ปี นาย ข. จะมีเงินรวมทั้งหมดกี่บาท?', array['10,025 บาท','10,125 บาท','10,250 บาท','10,500 บาท'], 2),
  ('ห้องประชุมแห่งหนึ่งมีเก้าอี้ 80 ตัว ถ้ามีผู้เข้าร่วมประชุม 75% ของจำนวนเก้าอี้ทั้งหมด จะมีเก้าอี้ว่างกี่ตัว?', array['15 ตัว','20 ตัว','25 ตัว','30 ตัว'], 1),
  ('ผลรวมของจำนวนเต็มสามจำนวนเรียงกันคือ 96 จงหาจำนวนที่น้อยที่สุด', array['31','32','33','34'], 0),
  ('สี่เหลี่ยมผืนผ้ามีด้านยาวยาวกว่าด้านกว้าง 5 เซนติเมตร ถ้าความยาวรอบรูปคือ 38 เซนติเมตร จงหาพื้นที่ของสี่เหลี่ยมผืนผ้านี้', array['72 ตารางเซนติเมตร','78 ตารางเซนติเมตร','84 ตารางเซนติเมตร','90 ตารางเซนติเมตร'], 2),
  ('ถ้า A=3, B=4, C=5 จงหาค่าของ (A+B)2−C2', array['12','18','24','30'], 2),
  ('พนักงานคนหนึ่งได้รับเงินเดือน 25,000 บาท เขาใช้จ่ายค่าอาหาร 30% ของเงินเดือน ค่าเดินทาง 15% ของเงินเดือน และเหลือเงินเท่าใด?', array['12,500 บาท','13,750 บาท','14,250 บาท','15,000 บาท'], 1),
  ('จงหาค่าของ 3/4 + 1/2 - 1/8', array['7/8','5/8','9/8','1/2'], 2),
  ('อายุของพ่อเป็นสามเท่าของอายุลูกชาย ถ้าปัจจุบันลูกชายอายุ 15 ปี อีก 5 ปีข้างหน้า พ่อจะมีอายุเท่าใด?', array['45 ปี','50 ปี','55 ปี','60 ปี'], 1),
  ('จงหาตัวเลขที่หายไปในอนุกรม: 1, 4, 9, 16, ___, 36', array['20','25','30','32'], 1),
  ('ถ้าสินค้าลดราคา 20% จากราคาปกติ 800 บาท จะต้องจ่ายเงินเท่าใด?', array['160 บาท','640 บาท','720 บาท','800 บาท'], 1),
  ('พนักงาน 5 คน ทำงานเสร็จใน 10 วัน ถ้าต้องการให้งานเสร็จภายใน 2 วัน จะต้องใช้พนักงานกี่คน?', array['10 คน','15 คน','20 คน','25 คน'], 3),
  ('จงหาค่าเฉลี่ยของชุดข้อมูล: 10, 15, 20, 25, 30', array['18','20','22','24'], 1),
  ('รูปสามเหลี่ยมมุมฉากมีด้านประกอบมุมฉากยาว 6 ซม. และ 8 ซม. ด้านตรงข้ามมุมฉากยาวเท่าใด?', array['9 ซม.','10 ซม.','12 ซม.','14 ซม.'], 1),
  ('อัตราส่วนของพื้นที่วงกลมสองวงคือ 4:9 ถ้าวงกลมวงแรกมีรัศมี 6 ซม. วงกลมวงที่สองมีรัศมีเท่าใด?', array['8 ซม.','9 ซม.','10 ซม.','12 ซม.'], 1),
  ('ถ้าวันนี้เป็นวันพุธ อีก 75 วันข้างหน้าจะเป็นวันอะไร?', array['วันจันทร์','วันอังคาร','วันพุธ','วันพฤหัสบดี'], 0),
  ('อนุกรมตัวอักษร: A, C, F, J, O, ___, Z', array['U','V','W','X'], 0),
  ('พนักงานขายได้รับค่าคอมมิชชั่น 5% จากยอดขาย ถ้าเขามียอดขาย 50,000 บาท เขาจะได้รับค่าคอมมิชชั่นเท่าใด?', array['2,000 บาท','2,500 บาท','3,000 บาท','3,500 บาท'], 1),
  ('ข้อใดใช้คำว่า ''การ'' นำหน้าคำกริยาได้ถูกต้อง?', array['การไปตลาด','การกินข้าว','การนอนหลับ','ถูกทุกข้อ'], 3),
  ('คำว่า ''วิเคราะห์'' มีความหมายใกล้เคียงกับคำใดมากที่สุด?', array['สังเคราะห์','แยกแยะ','รวบรวม','สรุป'], 1),
  ('ประโยคใดต่อไปนี้เป็นประโยคความซ้อน?', array['ฉันชอบกินข้าวผัด','พ่อและแม่ไปตลาด','เขาเป็นคนดีที่ทุกคนรัก','ฝนตกหนักมาก'], 2),
  ('สำนวน ''น้ำขึ้นให้รีบตัก'' มีความหมายตรงกับข้อใด?', array['เมื่อมีโอกาสดีควรรีบฉวยไว้','การตักน้ำเมื่อน้ำเต็มตลิ่ง','การรอคอยโอกาสที่เหมาะสม','การทำงานหนักเมื่อมีแรง'], 0),
  ('ข้อใดคือคำที่สะกดถูกต้อง?', array['โอกาศ','โอกาส','โอการ','โอกาด'], 1),
  ('''ความหลากหลายทางชีวภาพ'' หมายถึงอะไร?', array['ความแตกต่างของสิ่งมีชีวิตในระบบนิเวศ','การมีสิ่งมีชีวิตชนิดเดียวจำนวนมาก','การเปลี่ยนแปลงของสภาพภูมิอากาศ','การอยู่รอดของสิ่งมีชีวิตที่แข็งแรงที่สุด'], 0),
  ('ข้อใดใช้คำบุพบทได้ถูกต้อง?', array['เขาเดิน ''ไป'' โรงเรียน','เธอเขียนจดหมาย ''ถึง'' เพื่อน','หนังสือ ''บน'' โต๊ะ','ถูกทุกข้อ'], 3),
  ('จงเรียงลำดับประโยคต่อไปนี้ให้เป็นข้อความที่สมบูรณ์: ก. การออกกำลังกายเป็นประจำ ข. จะช่วยให้ร่างกายแข็งแรง ค. และลดความเสี่ยงของโรคต่างๆ ง. ซึ่งเป็นสิ่งสำคัญต่อสุขภาพที่ดี', array['ก ข ค ง','ก ง ข ค','ง ก ข ค','ข ค ก ง'], 1),
  ('คำว่า ''สัมฤทธิ์ผล'' มีความหมายใกล้เคียงกับคำใด?', array['ล้มเหลว','ประสบความสำเร็จ','เริ่มต้น','หยุดนิ่ง'], 1),
  ('ข้อใดคือคำที่สะกดผิด?', array['กะเพรา','กะทิ','กะหรี่','กระเพาะ'], 2),
  ('ประโยคใดมีความหมายกำกวม?', array['เขาเห็นตำรวจจับผู้ร้าย','แม่ซื้อเสื้อผ้าใหม่','น้องอ่านหนังสือเล่มนั้น','พ่อซ่อมรถยนต์'], 0),
  ('คำว่า ''อุปสรรค'' มีความหมายตรงข้ามกับคำใด?', array['ปัญหา','ขัดขวาง','ส่งเสริม','ขีดจำกัด'], 2),
  ('ข้อใดคือคำราชาศัพท์ที่ถูกต้องสำหรับ ''กิน'' (สำหรับพระมหากษัตริย์)?', array['เสวย','รับประทาน','ฉัน','บริโภค'], 0),
  ('''การพัฒนาที่ยั่งยืน'' หมายถึงอะไร?', array['การพัฒนาเศรษฐกิจเพียงอย่างเดียว','การพัฒนาที่ตอบสนองความต้องการของคนรุ่นปัจจุบันโดยไม่กระทบความสามารถของคนรุ่นหลัง','การพัฒนาที่เน้นการใช้ทรัพยากรธรรมชาติให้มากที่สุด','การพัฒนาที่มุ่งเน้นการเจริญเติบโตอย่างรวดเร็ว'], 1),
  ('ข้อใดใช้คำเชื่อมได้ถูกต้อง?', array['เขาชอบอ่านหนังสือ แต่ ดูโทรทัศน์','เธอจะไปตลาด หรือ ไปห้างสรรพสินค้า','ฝนตก ดังนั้น ถนนจึงเปียก','ถูกทุกข้อ'], 3),
  ('ข้อใดคือคำที่สะกดถูกต้อง?', array['ลายเซ็นต์','ลายเซ็น','ลายเซ็นต์','ลายเซน'], 1),
  ('''การมีส่วนร่วมของประชาชน'' มีความสำคัญอย่างไรในการบริหารราชการ?', array['ทำให้ประชาชนมีอำนาจเหนือเจ้าหน้าที่','ช่วยให้การตัดสินใจของภาครัฐสอดคล้องกับความต้องการของประชาชนมากขึ้น','เพิ่มภาระงานให้เจ้าหน้าที่','ทำให้กระบวนการทำงานล่าช้า'], 1),
  ('ข้อใดคือประโยคที่ใช้ภาษาพูด?', array['ดิฉันขอเรียนให้ทราบว่า','ผมจะไปทำธุระ','ท่านโปรดพิจารณา','เรียนท่านผู้มีเกียรติ'], 1),
  ('คำว่า ''นวัตกรรม'' หมายถึงอะไร?', array['การเลียนแบบสิ่งที่มีอยู่แล้ว','การประดิษฐ์คิดค้นสิ่งใหม่ๆ เพื่อเพิ่มมูลค่าหรือประโยชน์','การปรับปรุงสิ่งเดิมให้ดีขึ้นเล็กน้อย','การนำเข้าเทคโนโลยีจากต่างประเทศ'], 1),
  ('ข้อใดคือคำที่สะกดถูกต้อง?', array['อนุญาติ','อนุญาต','อณุญาติ','อณุญาต'], 1),
  ('''การสร้างความโปร่งใสในการทำงาน'' มีประโยชน์อย่างไร?', array['ลดการตรวจสอบจากภายนอก','สร้างความเชื่อมั่นและลดโอกาสการทุจริต','ทำให้การทำงานช้าลง','เพิ่มขั้นตอนการทำงาน'], 1),
  ('ข้อใดคือประโยคที่ใช้คำว่า ''ซึ่ง'' ได้ถูกต้อง?', array['เขาชอบกินข้าว ซึ่งอร่อยมาก','เธอไปโรงเรียน ซึ่งอยู่ไกล','ฉันเห็นนก ซึ่งบินอยู่บนฟ้า','ถูกทุกข้อ'], 3),
  ('สำนวน ''เข้าตามตรอก ออกตามประตู'' มีความหมายว่าอย่างไร?', array['การทำอะไรตามใจชอบ','การทำอะไรที่ถูกต้องตามระเบียบแบบแผน','การทำอะไรที่ซับซ้อน','การทำอะไรที่ผิดกฎหมาย'], 1),
  ('ข้อใดคือคำที่สะกดถูกต้อง?', array['ศรีษะ','ศรีษะ','ศีรษะ','ศีรษะ'], 2),
  ('''การบริการภาครัฐแบบเบ็ดเสร็จ ณ จุดเดียว'' (One Stop Service) มีประโยชน์อย่างไร?', array['เพิ่มจำนวนหน่วยงานที่ประชาชนต้องติดต่อ','ลดความสะดวกและรวดเร็วในการติดต่อราชการ','อำนวยความสะดวกให้ประชาชนติดต่อราชการได้ครบวงจรในที่เดียว','ทำให้ประชาชนต้องเดินทางหลายครั้ง'], 2)
  ) as q(question_text, options, correct_idx);

  -- ----- คำถามหมวด "ภาษาอังกฤษ" (25 ข้อ) -----
  insert into public.questions (category_id, question_text, options, correct_answer_index, explanation, difficulty, source, created_by)
  select v_english_id, q.question_text, q.options, q.correct_idx,
         '[ยังไม่มีคำอธิบายเฉลย — กรุณาเพิ่มผ่านหน้าจัดการคำถาม]', 'medium', 'manual', null
  from (values
  ('Choose the best answer to complete the sentence. "She _____ (work) at a hospital for five years."', array['work','works','worked','has worked'], 3),
  ('Choose the word that has the closest meaning to ''crucial''.', array['Unimportant','Essential','Minor','Optional'], 1),
  ('Identify the error in the sentence. "Despite of the rain, they went out for a walk in the park."', array['of','they','out','in'], 0),
  ('Choose the best response to the following conversation. A: "I''m sorry, I accidentally broke your favorite mug." B: "____________________"', array['"You are so careless!"','"It''s okay. Don''t worry about it."','"You should buy me a new one."','"I''m very angry with you."'], 1),
  ('Complete the sentence with the correct preposition. "The book is _____ the table."', array['in','at','on','under'], 2),
  ('Choose the sentence that is grammatically correct.', array['He don''t like coffee.','She is more taller than him.','They are going to travel next month.','We goes to the beach every summer.'], 2),
  ('Read the short passage and answer the question. "Climate change is a global issue that requires urgent action. Rising global temperatures are leading to more frequent and intense heatwaves, melting glaciers, and rising sea levels. These changes pose significant threats to ecosystems, human health, and economic stability. International cooperation and a shift towards renewable energy sources are vital to mitigate these impacts." What is the primary cause of climate change mentioned in the passage?', array['Volcanic eruptions','Human activities leading to rising global temperatures','Natural cycles of the Earth','Changes in ocean currents'], 1),
  ('Choose the word that is an antonym of ''optimistic''.', array['Hopeful','Positive','Pessimistic','Cheerful'], 2),
  ('Complete the sentence with the correct article. "I saw _____ elephant at the zoo."', array['a','an','the','no article'], 1),
  ('Choose the best response to the following conversation. A: "Would you like some more tea?" B: "____________________"', array['"No, I don''t."','"Yes, please. That would be lovely."','"I hate tea."','"I''m not thirsty."'], 1),
  ('Identify the error in the sentence. "She is more happier now than before."', array['is','happier','more','than'], 2),
  ('Choose the correct form of the word to complete the sentence. "The new policy will _____ the company''s productivity."', array['effect','affect','effecting','affected'], 1),
  ('What is the past tense of ''go''?', array['gone','goes','went','going'], 2),
  ('Choose the best answer to complete the sentence. "If I _____ (have) more time, I would travel the world."', array['have','had','will have','would have'], 1),
  ('Read the short passage and answer the question. "Artificial intelligence (AI) is rapidly transforming various industries, from healthcare to finance. AI-powered systems can analyze vast amounts of data, automate tasks, and even make predictions. While AI offers immense potential for efficiency and innovation, concerns about job displacement and ethical implications remain. Therefore, a balanced approach to AI development and deployment is essential." What is one potential benefit of AI mentioned in the passage?', array['Job displacement','Ethical implications','Efficiency and innovation','Data overload'], 2),
  ('Choose the word that is a synonym of ''ancient''.', array['Modern','Old','New','Recent'], 1),
  ('Complete the sentence with the correct relative pronoun. "This is the book _____ I told you about."', array['who','whom','which','whose'], 2),
  ('Choose the best response to the following conversation. A: "Could you please help me carry these boxes?" B: "____________________"', array['"No, I can''t."','"Sure, no problem."','"I''m too busy."','"Why should I?"'], 1),
  ('Identify the error in the sentence. "She is the most beautifulest girl in the class."', array['is','most','beautifulest','in'], 2),
  ('Choose the correct word to complete the sentence. "The weather forecast said it would be _____ tomorrow."', array['sunny','sunnily','sun','sunnier'], 0),
  ('What is the plural form of ''child''?', array['childs','childes','children','childen'], 2),
  ('Choose the best answer to complete the sentence. "He enjoys _____ (read) books in his free time."', array['read','to read','reading','reads'], 2),
  ('Read the short passage and answer the question. "The concept of ''work-life balance'' has gained significant attention in recent years. It refers to the idea of managing one''s professional and personal responsibilities effectively to achieve overall well-being. A good work-life balance can lead to reduced stress, improved mental health, and increased job satisfaction. Companies are increasingly recognizing the importance of this balance and implementing policies to support their employees." What is the main purpose of achieving work-life balance?', array['To increase working hours','To reduce personal responsibilities','To achieve overall well-being','To focus solely on professional growth'], 2),
  ('Choose the word that is an antonym of ''expand''.', array['Grow','Enlarge','Shrink','Widen'], 2),
  ('Complete the sentence with the correct verb tense. "By next year, I _____ (finish) my degree."', array['finish','finished','will finish','will have finished'], 3)
  ) as q(question_text, options, correct_idx);

  -- ----- คำถามหมวด "การเป็นข้าราชการที่ดี" (25 ข้อ) -----
  insert into public.questions (category_id, question_text, options, correct_answer_index, explanation, difficulty, source, created_by)
  select v_civil_service_id, q.question_text, q.options, q.correct_idx,
         '[ยังไม่มีคำอธิบายเฉลย — กรุณาเพิ่มผ่านหน้าจัดการคำถาม]', 'medium', 'manual', null
  from (values
  ('ตามพระราชบัญญัติระเบียบข้าราชการพลเรือน พ.ศ. 2551 ข้อใดคือลักษณะต้องห้ามของผู้ที่จะเข้ารับราชการเป็นข้าราชการพลเรือนสามัญ?', array['เป็นผู้มีหนี้สินล้นพ้นตัว','เป็นผู้เคยถูกลงโทษทางวินัยอย่างร้ายแรง','เป็นผู้เคยถูกจำคุกโดยคำพิพากษาถึงที่สุดให้จำคุก เว้นแต่เป็นความผิดที่ได้กระทำโดยประมาทหรือความผิดลหุโทษ','ถูกต้องทุกข้อ'], 3),
  ('การพิจารณาความดีความชอบของข้าราชการพลเรือนสามัญ ต้องยึดหลักใดเป็นสำคัญ?', array['หลักความอาวุโส','หลักความรู้ความสามารถและผลการปฏิบัติงาน','หลักความสัมพันธ์ส่วนตัว','หลักการอุปถัมภ์'], 1),
  ('ข้อใดคืออำนาจหน้าที่ของคณะกรรมการข้าราชการพลเรือน (ก.พ.) ที่เกี่ยวข้องกับการบริหารงานบุคคล?', array['กำหนดแผนพัฒนาเศรษฐกิจและสังคมแห่งชาติ','กำหนดนโยบายและหลักเกณฑ์การบริหารงานบุคคลของข้าราชการพลเรือน','พิจารณาอุทธรณ์คำสั่งทางปกครองของประชาชน','ตรวจสอบการทุจริตในภาครัฐ'], 1),
  ('ข้าราชการพลเรือนผู้ใดที่ประพฤติผิดวินัยอย่างร้ายแรง อาจได้รับโทษทางวินัยสูงสุดในข้อใด?', array['ภาคทัณฑ์','ตัดเงินเดือน','ลดขั้นเงินเดือน','ไล่ออก'], 3),
  ('ตามพระราชบัญญัติระเบียบข้าราชการพลเรือน พ.ศ. 2551 การแต่งตั้งข้าราชการให้ดำรงตำแหน่งประเภทบริหาร ต้องคำนึงถึงสิ่งใดเป็นสำคัญ?', array['ระยะเวลาการทำงาน','ประสบการณ์และความสามารถในการบริหาร','ความสัมพันธ์กับผู้บริหารระดับสูง','จำนวนวุฒิการศึกษาที่ได้รับ'], 1),
  ('ตามพระราชกฤษฎีกาว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546 การบริหารราชการเพื่อให้เกิด ''ประโยชน์สุขของประชาชน'' ต้องคำนึงถึงสิ่งใด?', array['การให้บริการที่สะดวก รวดเร็ว และมีคุณภาพ','การตอบสนองความต้องการของประชาชน','การลดขั้นตอนการปฏิบัติงาน','ถูกต้องทุกข้อ'], 3),
  ('ส่วนราชการต้องจัดให้มีการทบทวนภารกิจของตนเพื่อดำเนินการในข้อใด?', array['เพื่อเพิ่มจำนวนภารกิจให้มากขึ้น','เพื่อปรับปรุงภารกิจให้ทันสมัยหรือยกเลิกภารกิจที่ไม่จำเป็น','เพื่อคงภารกิจเดิมไว้ทั้งหมด','เพื่อมอบภารกิจให้เอกชนดำเนินการแทนทั้งหมด'], 1),
  ('การบริหารราชการเพื่อให้เกิด ''ความคุ้มค่า'' ตาม พ.ร.ฎ. นี้ หมายถึงข้อใด?', array['การใช้จ่ายงบประมาณให้มากที่สุด','การใช้ทรัพยากรอย่างประหยัดและเกิดประโยชน์สูงสุด','การสร้างผลงานโดยไม่คำนึงถึงต้นทุน','การจัดซื้อจัดจ้างที่แพงที่สุด'], 1),
  ('ข้อใดคือหลักการ ''การลดขั้นตอนการปฏิบัติงาน'' ตามพระราชกฤษฎีกาว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดีฯ?', array['การเพิ่มเอกสารที่ต้องใช้ในการติดต่อราชการ','การกำหนดระยะเวลาที่ยาวนานในการพิจารณาเรื่อง','การนำเทคโนโลยีมาใช้เพื่อลดความซ้ำซ้อนและอำนวยความสะดวก','การให้ประชาชนเดินทางไปติดต่อหลายหน่วยงาน'], 2),
  ('การประเมินผลการปฏิบัติราชการตาม พ.ร.ฎ. นี้ ควรเน้นที่สิ่งใดเป็นหลัก?', array['จำนวนบุคลากรในหน่วยงาน','ผลสัมฤทธิ์ของภารกิจและประสิทธิภาพ','ความเห็นส่วนตัวของผู้บริหาร','การเปรียบเทียบกับหน่วยงานอื่นโดยไม่มีเกณฑ์'], 1),
  ('ตามประมวลจริยธรรมข้าราชการพลเรือน ข้าราชการพึงปฏิบัติตนอย่างไรเกี่ยวกับความโปร่งใส?', array['เปิดเผยข้อมูลลับของทางราชการได้ตามใจชอบ','ปฏิบัติหน้าที่ด้วยความโปร่งใสและตรวจสอบได้','ปกปิดข้อมูลที่ไม่ต้องการให้ประชาชนทราบ','ไม่ต้องชี้แจงเหตุผลในการตัดสินใจ'], 1),
  ('หากข้าราชการพลเรือนได้รับมอบหมายให้ปฏิบัติหน้าที่ที่ขัดแย้งกับผลประโยชน์ส่วนตน ควรทำอย่างไร?', array['ปฏิบัติหน้าที่ต่อไปโดยไม่สนใจ','แจ้งผู้บังคับบัญชาเพื่อพิจารณามอบหมายให้ผู้อื่นทำแทน','ใช้โอกาสนี้เพื่อประโยชน์ส่วนตน','ลาออกจากราชการ'], 1),
  ('ข้อใดคือการแสดงออกถึงการมี ''จิตบริการ'' ของข้าราชการ?', array['ทำงานตามหน้าที่ที่ได้รับมอบหมายเท่านั้น','ให้บริการด้วยความเต็มใจ เอาใจใส่ และเป็นกันเอง','หลีกเลี่ยงการพบปะกับประชาชนโดยตรง','เน้นการปฏิบัติตามกฎระเบียบอย่างเคร่งครัดโดยไม่ยืดหยุ่น'], 1),
  ('ข้าราชการพลเรือนควรประพฤติตนเป็นแบบอย่างที่ดีในด้านใด?', array['การใช้ชีวิตที่หรูหราฟุ่มเฟือย','การเคารพกฎหมายและรักษาวินัยอย่างเคร่งครัด','การใช้เวลาราชการไปประกอบธุรกิจส่วนตัว','การรับอามิสสินจ้างจากผู้มีส่วนได้ส่วนเสีย'], 1),
  ('ตามพระราชบัญญัติมาตรฐานทางจริยธรรม พ.ศ. 2562 มาตรฐานทางจริยธรรมมีวัตถุประสงค์เพื่อสิ่งใด?', array['เพื่อกำหนดบทลงโทษทางอาญาแก่เจ้าหน้าที่รัฐ','เพื่อเป็นหลักเกณฑ์ในการประพฤติปฏิบัติของเจ้าหน้าที่ของรัฐ','เพื่อควบคุมการใช้จ่ายส่วนตัวของเจ้าหน้าที่รัฐ','เพื่อยกเลิกประมวลจริยธรรมเดิมทั้งหมด'], 1),
  ('ข้อใดเป็นหลักการสำคัญของมาตรฐานทางจริยธรรมตาม พ.ร.บ. นี้?', array['การยึดมั่นในประโยชน์ส่วนตน','การดำรงตนเป็นแบบอย่างที่ดี','การแสวงหาผลประโยชน์จากตำแหน่งหน้าที่','การไม่เปิดเผยข้อมูลใดๆ'], 1),
  ('หน่วยงานของรัฐมีหน้าที่อย่างไรตามพระราชบัญญัติมาตรฐานทางจริยธรรม พ.ศ. 2562?', array['ไม่ต้องจัดทำประมวลจริยธรรมของตนเอง','จัดทำประมวลจริยธรรมของตนเองให้สอดคล้องกับมาตรฐานทางจริยธรรม','กำหนดโทษทางวินัยที่ไม่ร้ายแรง','ตรวจสอบทรัพย์สินของเจ้าหน้าที่ทุกคน'], 1),
  ('ตามพระราชบัญญัติวิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539 การพิจารณาทางปกครองต้องดำเนินการโดยยึดหลักใด?', array['หลักความรวดเร็วเป็นสำคัญ','หลักความเป็นธรรมและโปร่งใส','หลักการใช้ดุลพินิจโดยอิสระ','หลักการให้เจ้าหน้าที่เป็นผู้ตัดสินใจแต่เพียงผู้เดียว'], 1),
  ('ก่อนการออกคำสั่งทางปกครองที่อาจกระทบสิทธิของคู่กรณี เจ้าหน้าที่ต้องดำเนินการในข้อใด?', array['ออกคำสั่งทันทีเพื่อความรวดเร็ว','แจ้งสิทธิและให้โอกาสคู่กรณีโต้แย้งแสดงพยานหลักฐาน','ปรึกษาผู้บังคับบัญชาเท่านั้น','ไม่จำเป็นต้องแจ้งคู่กรณีล่วงหน้า'], 1),
  ('''คำสั่งทางปกครอง'' ตามพระราชบัญญัติวิธีปฏิบัติราชการทางปกครองฯ ต้องมีลักษณะสำคัญในข้อใด?', array['เป็นการกระทำของเจ้าหน้าที่ที่มีผลกระทบต่อสถานภาพของสิทธิหรือหน้าที่ของบุคคล','เป็นข้อคิดเห็นหรือข้อเสนอแนะภายในหน่วยงาน','เป็นการลงนามในบันทึกข้อความภายใน','เป็นการประชุมหารือเพื่อวางแผนงาน'], 0),
  ('คู่กรณีที่ไม่เห็นด้วยกับคำสั่งทางปกครอง มีสิทธิอุทธรณ์คำสั่งดังกล่าวภายในกี่วันนับแต่วันที่ได้รับแจ้งคำสั่ง?', array['7 วัน','15 วัน','30 วัน','60 วัน'], 1),
  ('ตามพระราชบัญญัติความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539 หากเจ้าหน้าที่กระทำละเมิดต่อบุคคลภายนอกในการปฏิบัติหน้าที่โดยไม่จงใจหรือประมาทเลินเล่ออย่างร้ายแรง ใครเป็นผู้รับผิดชอบค่าสินไหมทดแทน?', array['เจ้าหน้าที่ผู้กระทำละเมิดต้องรับผิดชอบเองทั้งหมด','หน่วยงานของรัฐที่เจ้าหน้าที่สังกัดต้องรับผิดชอบ','ผู้เสียหายต้องรับผิดชอบความเสียหายเอง','เจ้าหน้าที่และหน่วยงานของรัฐรับผิดชอบร่วมกัน'], 1),
  ('ในกรณีที่หน่วยงานของรัฐได้ชดใช้ค่าสินไหมทดแทนให้แก่ผู้เสียหายไปแล้ว หน่วยงานของรัฐมีสิทธิเรียกให้เจ้าหน้าที่ชดใช้ค่าสินไหมทดแทนคืนได้ในกรณีใด?', array['เจ้าหน้าที่กระทำละเมิดโดยสุจริต','เจ้าหน้าที่กระทำละเมิดโดยความประมาทเล็กน้อย','เจ้าหน้าที่กระทำละเมิดโดยจงใจหรือประมาทเลินเล่ออย่างร้ายแรง','หน่วยงานของรัฐเรียกคืนได้ทุกกรณีเพื่อรักษาผลประโยชน์ของรัฐ'], 2),
  ('''เจ้าหน้าที่'' ตามพระราชบัญญัติความรับผิดทางละเมิดของเจ้าหน้าที่ฯ หมายถึงบุคคลใด?', array['เฉพาะข้าราชการพลเรือน','เฉพาะพนักงานรัฐวิสาหกิจ','ข้าราชการ พนักงาน ลูกจ้าง หรือผู้ปฏิบัติงานอื่นในหน่วยงานของรัฐ','เฉพาะผู้บริหารระดับสูงในหน่วยงานของรัฐ'], 2),
  ('ข้อใดไม่เข้าข่าย ''การปฏิบัติหน้าที่'' ตามพระราชบัญญัติความรับผิดทางละเมิดของเจ้าหน้าที่ฯ?', array['เจ้าหน้าที่ปฏิบัติงานตามคำสั่งของผู้บังคับบัญชา','เจ้าหน้าที่ใช้รถยนต์ของทางราชการเพื่อไปปฏิบัติภารกิจส่วนตัว','เจ้าหน้าที่เข้าร่วมประชุมเพื่อพิจารณางานของหน่วยงาน','เจ้าหน้าที่ให้คำปรึกษาแก่ประชาชนในเรื่องที่อยู่ในอำนาจหน้าที่'], 1)
  ) as q(question_text, options, correct_idx);

  raise notice 'Seed เสร็จสมบูรณ์: 3 หมวดหมู่, 1 ปี, 100 คำถาม';

end $$;

-- ----- system_config เริ่มต้น (ค่า default อยู่ใน schema แล้ว แค่ยืนยันว่ามี 2 แถว) -----
insert into public.system_config (key) values ('public'), ('secrets')
